// biome-ignore lint/suspicious/noTsIgnore: the file exists only after a build, so @ts-expect-error fails once it does
// @ts-ignore .open-next/worker.js is generated by `opennextjs-cloudflare build`
import nextWorker from './.open-next/worker.js'

type Env = {
  CRON_SECRET: string
}

// The Worker entry (wrangler.jsonc main): OpenNext's fetch handler plus the daily Cron Trigger, which runs
// /api/cron/daily in-process with the Bearer secret the route checks; a failed run throws, so Cron Events show it
export default {
  fetch: nextWorker.fetch,
  async scheduled(_controller: unknown, env: Env, context: unknown) {
    const request = new Request('https://saldo.internal/api/cron/daily', {
      headers: {
        authorization: `Bearer ${env.CRON_SECRET}`,
      },
    })
    const response = await nextWorker.fetch(request, env, context)

    if (!response.ok) {
      throw new Error(`/api/cron/daily answered ${response.status}`)
    }
  },
}
